package org.lostlittlescripts.codingbat.java.warmup1;

import org.junit.Test;
import static org.junit.Assert.*;

public class diff21SolutionTest {
    @Test
    public void testSolution() {
        diff21Solution classUnderTest = new diff21Solution();
        int[][] testcases = {
                { 19, 2 },
                { 10, 11 },
                { 21, 0 },
                { 22, 2 },
                { 25, 8 },
                { 30, 18 },
                { 0, 21 },
                { 1, 20 },
                { 2, 19 },
                { -1, 22 },
                { -2, 23 },
                { 50, 58 },
        };

        for (int i = 0; i < testcases.length; i++) {
            var res = classUnderTest.diff21(testcases[i][0]);
            System.out.printf("%d => %d (%s)%n", testcases[i][0], res, res == testcases[i][1] ? "PASSED" : "FAILED");
            assertEquals(testcases[i][1], res);
        }
    }
}
